import {Vector3} from 'three';
import {componentDefaultValues,objectComponents,validComponentProperties} from './scene-components.js';
import {sceneWorldMatrix} from './scene-runtime.js';
import {clothPins,clothLocalPoint} from './cloth-config.js';
const localPoint=(p,i,out)=>p.particles?out.fromArray(p.start).lerp(new Vector3(...p.end),i/(p.particles-1)):clothLocalPoint(p,i,out);
const pinsFor=p=>clothPins(p.particles?{...p,columns:p.particles,rows:1}:p);
const xyz=v=>({x:v.x,y:v.y,z:v.z}),vector=v=>Array.isArray(v)&&v.length===3&&v.every(Number.isFinite);
export class DeformableWorld{
 constructor(space,objects,{queryOnly=false,frame,type='Cloth'}={}){this.type=type;this.is2D=type==='Rope2D';this.debugKey=this.is2D?'rope':'cloth';this.space=space;this.objects=objects;this.queryOnly=queryOnly;this.frame=frame;this.items=new Map();this.point=new Vector3();}
 remove(id){const item=this.items.get(id);if(!item)return;for(const handle of item.colliders)this.space.colliders.delete(handle);this.space.world.removeSoftBody(item.body);delete item.object.gameplayDebug?.[this.debugKey];this.frame?.(item.object,null);this.items.delete(id);}
 sync(candidates=this.objects){if(this.queryOnly||!candidates.length&&!this.items.size)return;const active=new Set();for(const object of candidates){if(object.poolActive===false)continue;const components=objectComponents(object).filter(c=>c.type===this.type&&c.properties?.enabled!==false);if(components.length>1)throw Error('같은 변형체 컴포넌트는 오브젝트마다 하나만 추가하세요.');const component=components[0];if(!component)continue;if(objectComponents(object).some(c=>c.type===(this.is2D?'Rigidbody':'Rigidbody2D')&&c.properties?.enabled!==false))throw Error('변형체와 강체의 물리 차원이 일치해야 해요.');const p={...componentDefaultValues(this.type),...component.properties};if(!validComponentProperties(this.type,p))throw Error('변형체의 입자·물성·고정 영역을 확인하세요.');active.add(object.id);const matrix=sceneWorldMatrix(object,this.objects),scale=new Vector3().setFromMatrixScale(matrix),signature=JSON.stringify([{...p,force:undefined},scale.toArray()]);let item=this.items.get(object.id);if(item?.signature===signature){item.object=object;item.component=component;item.p=p;const enabled=object.collisionEnabled!==false;if(item.collisionEnabled!==enabled){for(const handle of item.colliders)this.space.colliders.get(handle)?.collider.setEnabled(enabled);item.collisionEnabled=enabled;item.body.wakeUp();}continue;}
 const {R,world}=this.space,origin=localPoint(p,0,new Vector3()).applyMatrix4(matrix);let desc;
 if(this.is2D){const end=localPoint(p,p.particles-1,new Vector3()).applyMatrix4(matrix);desc=R.SoftBodyDesc.rope(xyz(origin),xyz(end),p.particles);}else{const du=localPoint(p,p.rows,new Vector3()).applyMatrix4(matrix).sub(origin),dv=localPoint(p,1,new Vector3()).applyMatrix4(matrix).sub(origin);desc=R.SoftBodyDesc.cloth(xyz(origin),xyz(du),xyz(dv),p.columns,p.rows);}
 const material=R.SoftBodyMaterial.uniform(p.frequency,p.dampingRatio);material.bendSoftness={naturalFrequency:p.bendFrequency,dampingRatio:p.dampingRatio};desc.setMass(p.mass).setPinnedParticles([...pinsFor(p)]).setMaterial(material).setParticleRadius(p.thickness).setSelfContacts(p.selfCollision).setLinearDamping(p.drag).setGravityScale(p.gravityScale).setAdditionalPgsIterations(p.iterations).setCanSleep(p.canSleep);
 if(p.collision){desc.setSurfaceCollider(R.ColliderDesc.ball(p.thickness).setEnabled(object.collisionEnabled!==false).setFriction(p.friction).setRestitution(p.restitution).setActiveHooks(R.ActiveHooks.FILTER_CONTACT_PAIRS|R.ActiveHooks.FILTER_INTERSECTION_PAIRS).setActiveCollisionTypes(R.ActiveCollisionTypes.ALL));}else desc.setNoSurfaceCollider();
 const body=world.createSoftBody(desc),colliders=[];try{for(let i=0;i<body.numMeshes();i++){const collider=body.meshCollider(i);if(collider)colliders.push(collider.handle);}}catch(error){world.removeSoftBody(body);throw error;}
 this.remove(object.id);item={object,component,p,signature,body,colliders,pins:new Map([...pinsFor(p)].map(i=>[i,localPoint(p,i,new Vector3())])),generation:(item?.generation||0)+1,version:0,matrix:matrix.clone(),dirty:true,collisionEnabled:object.collisionEnabled!==false};this.items.set(object.id,item);for(let i=0;i<body.numMeshes();i++){const collider=body.meshCollider(i);if(collider)this.space.colliders.set(collider.handle,{object,component,p:{layer:p.layer,mask:p.mask,collisionMode:'both',trigger:false},collider,is2D:this.is2D,softBody:true,signature});}this.publishItem(item);
 }for(const id of this.items.keys())if(!active.has(id))this.remove(id);}
 require(object){const item=this.items.get(object.id);if(!item)throw Error('활성 변형체 컴포넌트가 필요해요.');return item;}
 index(item,index){if(!Number.isInteger(index)||index<0||index>=item.body.numParticles())throw Error('변형체 입자 번호 범위를 확인하세요.');}
 pin(object,index,pinned){const item=this.require(object);this.index(item,index);if(typeof pinned!=='boolean')throw Error('천 고정 상태를 확인하세요.');item.body.setParticlePinned(index,pinned);if(pinned){const point=item.body.particlePosition(index);item.pins.set(index,new Vector3(point.x,point.y,this.is2D?sceneWorldMatrix(object,this.objects).elements[14]:point.z).applyMatrix4(sceneWorldMatrix(object,this.objects).invert()));}else item.pins.delete(index);item.body.wakeUp();item.dirty=true;}
 impulse(object,impulse,index=-1){const item=this.require(object);if(!vector(impulse)||this.is2D&&impulse[2]!==0)throw Error('천 충격량을 확인하세요.');if(index===-1)item.body.applyImpulse(xyz(new Vector3(...impulse)),true);else{this.index(item,index);item.body.applyParticleImpulse(index,xyz(new Vector3(...impulse)),true);}item.dirty=true;}
 attach(object,index,target){const item=this.require(object);this.index(item,index);if(target){const r=this.space.bodies.get(target.id);if(!r)throw Error('같은 차원의 활성 강체가 필요해요.');item.body.detachParticle(index);item.body.setParticlePinned(index,false);item.pins.delete(index);item.body.attachParticle(index,r.body);}else item.body.detachParticle(index);item.body.wakeUp();item.dirty=true;}
 reset(object){const item=this.require(object);item.signature=null;this.sync();}
 step(){for(const item of this.items.values()){const matrix=sceneWorldMatrix(item.object,this.objects),moved=!item.matrix.equals(matrix);if(moved){for(const[index,local]of item.pins){this.point.copy(local).applyMatrix4(matrix);item.body.setParticleKinematicTarget(index,xyz(this.point));}item.matrix.copy(matrix);item.body.wakeUp();item.dirty=true;}item.body.resetForces(false);if(item.p.force.some(v=>v!==0))item.body.addForce({x:item.p.force[0],y:item.p.force[1],z:item.p.force[2]},true);}}
 publishItem(item){const sleeping=item.body.isSleeping();if(sleeping&&!item.dirty&&item.lastSleeping===sleeping)return;item.lastSleeping=sleeping;item.version++;const count=item.body.numParticles(),summary={particles:count,pinned:item.pins.size,attachments:item.body.numAttachments(),sleeping,generation:item.generation,version:item.version};item.object.gameplayDebug={...item.object.gameplayDebug,[this.debugKey]:summary};if(this.frame){item.frame??={positions:null,version:0,generation:item.generation};const positions=item.body.particlePositions();if(this.is2D){item.frame.positions??=new Float32Array(count*3);const z=sceneWorldMatrix(item.object,this.objects).elements[14];for(let i=0;i<count;i++){item.frame.positions[i*3]=positions[i*2];item.frame.positions[i*3+1]=positions[i*2+1];item.frame.positions[i*3+2]=z;}}else item.frame.positions=positions;item.frame.version=item.version;this.frame(item.object,item.frame);}item.dirty=false;}
 publish(){for(const item of this.items.values())this.publishItem(item);}
 page(object,{offset=0,limit=64}={}){const item=this.require(object);if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>256)throw Error('천 입자 페이지 범위를 확인하세요.');const total=item.body.numParticles(),displayZ=this.is2D?sceneWorldMatrix(object,this.objects).elements[14]:0,items=[],point={x:0,y:0,z:0},velocity={x:0,y:0,z:0};for(let i=offset;i<Math.min(offset+limit,total);i++){item.body.particlePosition(i,point);item.body.particleVelocity(i,velocity);items.push({index:i,position:[point.x,point.y,this.is2D?displayZ:point.z],velocity:[velocity.x,velocity.y,this.is2D?0:velocity.z],pinned:item.body.isParticlePinned(i)});}return{...item.object.gameplayDebug?.[this.debugKey],pinned:item.pins.size,attachments:item.body.numAttachments(),sleeping:item.body.isSleeping(),offset,total,items,nextOffset:offset+limit<total?offset+limit:null};}
 dispose(){for(const id of [...this.items.keys()])this.remove(id);}
}
